// ProductCard.jsx — React Practitioner Level
import { useState, useEffect } from 'react';

export default function ProductCard({ productId }) {
  const [product, setProduct] = useState(null);
  const [quantity, setQuantity] = useState(1);
  const [adding, setAdding] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch(`/api/products/${productId}`)
      .then(r => r.ok ? r.json() : Promise.reject('Not found'))
      .then(setProduct)
      .catch(() => setError('Failed to load product.'));
  }, [productId]);

  async function handleAddToCart(e) {
    e.preventDefault();
    setAdding(true);
    try {
      await fetch('/api/cart', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ productId, quantity }),
      });
    } catch {
      setError('Could not add to cart. Try again.');
    } finally {
      setAdding(false);
    }
  }

  if (error) return <p role="alert" className="error">{error}</p>;
  if (!product) return <p>Loading…</p>;

  return (
    <article className="product-card" aria-label={product.name}>
      <img src={product.imageUrl} alt={product.name} className="product-card__image" />
      <div className="product-card__body">
        <h2 className="product-card__title">{product.name}</h2>
        <p className="product-card__description">{product.description}</p>
        <p className="product-card__price" aria-label={`Price: ${product.price}`}>
          {new Intl.NumberFormat('en-NG', { style: 'currency', currency: 'NGN' }).format(product.price)}
        </p>
        <form onSubmit={handleAddToCart} className="product-card__form">
          <label htmlFor={`qty-${productId}`} className="sr-only">Quantity</label>
          <input
            id={`qty-${productId}`}
            type="number"
            min="1"
            max="99"
            value={quantity}
            onChange={e => setQuantity(Number(e.target.value))}
            className="product-card__qty"
          />
          <button type="submit" disabled={adding} className="product-card__cta">
            {adding ? 'Adding…' : 'Add to Cart'}
          </button>
        </form>
      </div>
    </article>
  );
}

/* product-card.css */
.product-card {
  display: grid;
  grid-template-columns: 1fr;
  max-width: 400px;
  border-radius: 12px;
  box-shadow: 0 2px 16px rgba(0,0,0,0.1);
  overflow: hidden;
  font-family: system-ui, sans-serif;
}
@media (min-width: 600px) {
  .product-card { grid-template-columns: 180px 1fr; max-width: 680px; }
}
.product-card__image { width: 100%; aspect-ratio: 4/3; object-fit: cover; }
.product-card__body { padding: 1.25rem; display: flex; flex-direction: column; gap: 0.75rem; }
.product-card__title { font-size: 1.2rem; font-weight: 700; }
.product-card__price { font-size: 1.1rem; font-weight: 600; color: #1a6b3c; }
.product-card__form { display: flex; gap: 0.5rem; align-items: center; }
.product-card__qty { width: 60px; padding: 0.4rem; border: 1px solid #ccc; border-radius: 4px; }
.product-card__cta {
  flex: 1; padding: 0.6rem 1rem; background: #1a6b3c; color: #fff;
  border: none; border-radius: 6px; cursor: pointer; font-size: 0.95rem;
}
.product-card__cta:disabled { opacity: 0.6; cursor: not-allowed; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }
.error { color: #c00; padding: 1rem; }

