import { useState, useEffect } from 'react';

export default function ProductCard({ productId }) {
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [cartMsg, setCartMsg] = useState('');

  useEffect(() => {
    setLoading(true);
    fetch(`/api/products/${productId}`)
      .then(res => res.json())
      .then(data => { setProduct(data); setLoading(false); })
      .catch(() => setLoading(false));
  }, [productId]);

  const addToCart = async () => {
    try {
      await fetch('/api/cart', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({ productId, quantity: 1 }),
      });
      setCartMsg('Added to cart!');
      setTimeout(() => setCartMsg(''), 3000);
    } catch {
      setCartMsg('Error. Try again.');
    }
  };

  if (loading) return <div className="card-loading">Loading product...</div>;
  if (!product) return <div className="card-error">Product not found.</div>;

  return (
    <article className="product-card">
      <img src={product.imageUrl} alt={product.name} className="product-card__img" />
      <div className="product-card__content">
        <h2 className="product-card__name">{product.name}</h2>
        <p className="product-card__desc">{product.description}</p>
        <strong className="product-card__price">₦{product.price?.toLocaleString()}</strong>
        <button onClick={addToCart} className="product-card__btn" type="button">
          Add to Cart
        </button>
        {cartMsg && <p className="product-card__msg" aria-live="polite">{cartMsg}</p>}
      </div>
    </article>
  );
}

